/**
 * Route-to-story ledger: every served route names the user stories whose
 * success criteria it serves, or the reason it has none, and every story no
 * route cites says why it has no route of its own. The route-wiring crawl suite
 * checks it both ways against the live route table and the story catalogue's
 * headings, so a new route, a removed route, a renamed story or a story that
 * silently lost its route fails until the ledger is updated.
 *
 * A `needs-ruling` entry is a served surface no story owns: unintended scope
 * until the maintainer either writes its story or removes it.
 */
export type NoStoryReason = 'test-harness' | 'machine-endpoint' | 'compatibility-redirect' | 'needs-ruling';
export type RouteStory =
  | { stories: readonly string[] }
  | { none: NoStoryReason; why: string };

